// What an agent may do, bits for `levels`: read mail
#define PE_AGENT_READ 1

// Organize it: read state, flags, junk, moves, deletes to Deleted Items
#define PE_AGENT_ORGANIZE 2

// Write drafts
#define PE_AGENT_DRAFTS 4

// Send, each message after the user says yes
#define PE_AGENT_SEND 8

// What a program the user lets in is offered first
#define PE_AGENT_DEFAULT 3

// How long a message an agent sent waits in the Outbox, in seconds
#define PE_AGENT_SEND_DELAY 30

// The levels an agent may be given, as the windows offer them: `count` of them
#define PE_AGENT_LEVEL_COUNT 4

// For `pe_core_open_with`: passwords and sign-ins are kept for this run only, not in the Credential Manager
// (test runs, a shared computer)
#define PE_OPEN_MEMORY_PASSWORDS 1

// What the reading pane shows instead of a message (`pe_reader_page`)
typedef enum PeReaderState {
  // No message is selected
  PE_READER_STATE_NO_MESSAGE = 0,
  // The message selected is being downloaded (after `pe_message_open`, before `MessageReady`)
  PE_READER_STATE_DOWNLOADING = 1,
  // It could not be downloaded (`MessageFailed`): `failure` and `reason` are the event's
  PE_READER_STATE_FAILED = 2,
} PeReaderState;

typedef enum PeFailureKind {
  PE_FAILURE_KIND_NONE = 0,
  // Not reachable now, try again later
  PE_FAILURE_KIND_NETWORK = 1,
  // TLS failed
  PE_FAILURE_KIND_SECURITY = 2,
  // The password was refused, or there is none
  PE_FAILURE_KIND_AUTHENTICATION = 3,
  PE_FAILURE_KIND_OTHER = 4,
} PeFailureKind;

typedef enum PeAgentAskKind {
  // Answered already, or no such question
  PE_AGENT_ASK_KIND_NONE = 0,
  // A program wants to connect: `pe_agent_connect_info`, answered with `pe_agent_answer_connect`
  PE_AGENT_ASK_KIND_CONNECT = 1,
  // An agent wants to send a message: `pe_agent_send_info`, answered with `pe_agent_answer_send`
  PE_AGENT_ASK_KIND_SEND = 2,
} PeAgentAskKind;

typedef enum PeAgentSendAnswer {
  // Into the Outbox, to go after PE_AGENT_SEND_DELAY seconds
  PE_AGENT_SEND_ANSWER_SEND = 0,
  // Nothing sent: the draft comes back, for the window that writes a message
  PE_AGENT_SEND_ANSWER_COMPOSE = 1,
  PE_AGENT_SEND_ANSWER_DONT_SEND = 2,
} PeAgentSendAnswer;

typedef enum PeEventKind {
  PE_EVENT_KIND_SYNC_STARTED = 1,
  // Comes after everything the sync found, failures included; `failure` is what kept it from finishing, `None`
  // when it did (the account is online)
  PE_EVENT_KIND_SYNC_FINISHED = 2,
  // The folder list of `account` changed
  PE_EVENT_KIND_FOLDERS_CHANGED = 3,
  // The messages of `folder` or their flags changed
  PE_EVENT_KIND_FOLDER_CHANGED = 4,
  // `pe_message_view` can show `folder`/`uid` now
  PE_EVENT_KIND_MESSAGE_READY = 5,
  // Work for `account` failed: `failure` and `message` say what
  PE_EVENT_KIND_FAILED = 6,
  // A message from `account` was sent; `message` is its subject
  PE_EVENT_KIND_MESSAGE_SENT = 7,
  // The lookup `uid` of `pe_autoconfig_start` is done: `pe_autoconfig_result`
  PE_EVENT_KIND_AUTOCONFIG_DONE = 8,
  // The sign-in `uid` of `pe_sign_in_begin` finished: `pe_sign_in_result`
  PE_EVENT_KIND_SIGN_IN_DONE = 9,
  // The view `uid` of `pe_message_view_start` is built: `pe_message_view_result`
  PE_EVENT_KIND_VIEW_READY = 10,
  // The Outbox of `account` changed: a message went in or out, or did not go: `pe_outbox`
  PE_EVENT_KIND_OUTBOX_CHANGED = 11,
  // The draft whose Message-ID is `detail` is in the Drafts of `account` on the server; when `message` is not
  // NULL it was not saved, and that says why
  PE_EVENT_KIND_DRAFT_SAVED = 12,
  // The check `uid` of `pe_sign_in_app_check` is done: `pe_sign_in_app_check_result`
  PE_EVENT_KIND_SIGN_IN_APP_CHECKED = 13,
  // New unread mail in the Inbox `folder` of `account`: `count` messages, `uid` the newest, `message` who it is
  // from and `detail` its subject
  PE_EVENT_KIND_NEW_MAIL = 14,
  // The unsubscribe `uid` of `pe_unsubscribe` is done; `message` says why not when it is not NULL
  PE_EVENT_KIND_UNSUBSCRIBED = 15,
  // The logo `uid` of `pe_logo_start` is drawn, or there was none: `pe_logo_result`
  PE_EVENT_KIND_LOGO_READY = 16,
  // `folder`/`uid` (opened with `pe_message_open`) could not be downloaded: `failure` and `message` say why, for
  // `pe_reader_page`. Opening it again tries again
  PE_EVENT_KIND_MESSAGE_FAILED = 17,
  // An AI agent needs the user to answer question `uid`: `pe_agent_ask_kind`
  PE_EVENT_KIND_AGENT_ASK = 18,
  // What AI agents did changed: `pe_agent_log`
  PE_EVENT_KIND_AGENT_LOG_CHANGED = 19,
} PeEventKind;

