  // What an added app was saved with (empty and 0 for a built-in client); never its secret
  const char *client_id;
  bool has_secret;
  const char *scopes;
  const char *imap_host;
  uint16_t imap_port;
  enum PeSecurity imap_security;
  const char *smtp_host;
  uint16_t smtp_port;
